-- Diagnostico apos importacao
SELECT 'usuarios_total' AS indicador, COUNT(*) AS valor FROM users;
SELECT 'usuarios_com_carteira' AS indicador, COUNT(*) AS valor FROM users WHERE cliente_id IS NOT NULL;
SELECT 'usuarios_com_turno' AS indicador, COUNT(*) AS valor FROM users WHERE turno_id IS NOT NULL;
SELECT 'usuarios_com_superior' AS indicador, COUNT(*) AS valor FROM users WHERE supervisor_id IS NOT NULL;
SELECT 'usuarios_com_escopo' AS indicador, COUNT(DISTINCT user_id) AS valor FROM user_campanhas WHERE ativo = 1;
SELECT 'escopos_total' AS indicador, COUNT(*) AS valor FROM user_campanhas WHERE ativo = 1;
SELECT u.name, u.email, cg.nome AS cargo, tu.nome AS turno, cl.nome AS carteira, sup.name AS superior, COUNT(uc.campanha_id) AS campanhas FROM users u LEFT JOIN cargos cg ON cg.id = u.cargo_id LEFT JOIN turnos tu ON tu.id = u.turno_id LEFT JOIN clientes cl ON cl.id = u.cliente_id LEFT JOIN users sup ON sup.id = u.supervisor_id LEFT JOIN user_campanhas uc ON uc.user_id = u.id AND uc.ativo = 1 GROUP BY u.id, u.name, u.email, cg.nome, tu.nome, cl.nome, sup.name ORDER BY u.name LIMIT 20;
